<template>
  <main class="page"><RouterLink class="back" to="/cardapios">← Voltar ao cardápio</RouterLink><span class="kicker">QUASE LÁ</span><h1>Conte sobre seu evento</h1><p class="lead">Sua solicitação será enviada para a equipe Brasiva. O orçamento final será confirmado após conversarmos com você.</p>
    <section class="summary"><h2>Seleção</h2><p v-if="!pedido.itens.length">Seu pedido ainda não tem itens. <RouterLink to="/cardapios">Escolha opções no cardápio</RouterLink>.</p><div v-for="item in pedido.itens" :key="item.id" class="line"><span>{{ item.quantidade }} × {{ item.nome }}</span><b>{{ item.sob_orcamento ? 'Sob orçamento' : moeda(Number(item.valor) * item.quantidade) }}</b></div><div v-if="pedido.itens.length" class="total"><span>Estimativa dos itens</span><b>{{ moeda(pedido.total) }}</b></div></section>
    <form @submit.prevent="enviar"><div class="fields"><label>Seu nome<input v-model.trim="form.nome" required autocomplete="name"></label><label>E-mail<input v-model.trim="form.email" type="email" required autocomplete="email"></label><label>Telefone / WhatsApp<input v-model.trim="form.telefone" required autocomplete="tel"></label><label>Tipo de evento<input v-model.trim="form.tipo_evento" required placeholder="Ex.: aniversário"></label><label>Data do evento<input v-model="form.data_evento" type="date" required></label><label>Número de convidados<input v-model.number="form.convidados" type="number" min="1" required></label><label class="wide">Conte mais (opcional)<textarea v-model.trim="form.observacoes" rows="4"></textarea></label></div><p v-if="erro" class="error">{{ erro }}</p><p v-if="sucesso" class="success">Solicitação enviada! Nossa equipe entrará em contato para confirmar os detalhes.</p><button class="submit" type="submit" :disabled="enviando || !pedido.itens.length">{{ enviando ? 'Enviando…' : 'Enviar solicitação' }} <span>→</span></button></form>
  </main>
</template>
<script setup>
import { reactive, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { usePedidoStore } from '../stores/pedido'
const pedido = usePedidoStore(); const router = useRouter(); const enviando = ref(false); const erro = ref(''); const sucesso = ref(false)
const form = reactive({ nome: '', email: '', telefone: '', tipo_evento: '', data_evento: '', convidados: 1, observacoes: '' })
const moeda = (valor) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(valor)
async function enviar() { enviando.value = true; erro.value = ''; try { await pedido.enviar(form); sucesso.value = true; window.scrollTo({ top: 0, behavior: 'smooth' }) } catch (error) { erro.value = error.response?.data ? Object.values(error.response.data).flat().join(' ') : 'Não foi possível enviar agora. Confira sua conexão e tente novamente.' } finally { enviando.value = false } }
</script>
<style scoped>
.page{max-width:850px;margin:auto;padding:125px 24px 90px}.back{display:block;color:#8c3428;text-decoration:none;font-weight:700;margin-bottom:35px}.kicker{font-size:.72rem;letter-spacing:.15em;color:#a2533d;font-weight:800}.page h1{font:500 clamp(2.4rem,5vw,4rem) Georgia,serif;color:#41241d;margin:15px 0}.lead{color:#76645b;line-height:1.7;margin-bottom:30px}.summary{background:#fff4e7;border-radius:20px;padding:24px;margin-bottom:28px}.summary h2{font:1.5rem Georgia;margin-bottom:15px;color:#41241d}.summary a{color:#8c3428}.line,.total{display:flex;justify-content:space-between;gap:20px;padding:10px 0;color:#60493f}.total{border-top:1px solid #e5cbb7;margin-top:8px;padding-top:16px;font-weight:800;color:#8c3428}.fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.fields label{display:grid;gap:8px;font-size:.9rem;font-weight:700;color:#4e352d}.fields input,.fields textarea{width:100%;border:1px solid #dfd0c5;border-radius:11px;padding:13px;font:inherit;background:#fff}.wide{grid-column:1/-1}.submit{margin-top:24px;border:0;border-radius:40px;background:#8c3428;color:#fff;padding:16px 23px;font:700 1rem inherit;cursor:pointer}.submit:disabled{opacity:.55;cursor:not-allowed}.submit span{margin-left:15px}.error{color:#a32121;margin-top:15px}.success{color:#27643b;margin-top:15px}@media(max-width:560px){.fields{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
